SourceCode.Declaration:
/// <summary>
/// This class holds the parameters used to get item base price from the table <c>GUPItemBasePrice</c>.
/// </summary>
public class GUPItemBasePriceParameter
{
    GUPBasePriceType    priceType;
    ItemId              itemId;
    InventDimId         inventDimId;
    TransDate           transDate;
    UnitOfMeasureSymbol unitId;
    CurrencyCode        currency;

}

Method.Source:
public static GUPItemBasePriceParameter construct()
{
    return new GUPItemBasePriceParameter();
}

public GUPBasePriceType parmPriceType(GUPBasePriceType _priceType = priceType)
{
    priceType = _priceType;
    return priceType;
}

public ItemId parmItemId(ItemId _itemId = itemId)
{
    itemId = _itemId;
    return itemId;
}

public InventDimId parmInventDimId(InventDimId _inventDimId = inventDimId)
{
    inventDimId = _inventDimId;
    return inventDimId;
}

public TransDate parmTransDate(TransDate _transDate = transDate)
{
    transDate = _transDate;
    return transDate;
}

public UnitOfMeasureSymbol parmUnitId(UnitOfMeasureSymbol _unitId = unitId)
{
    unitId = _unitId;
    return unitId;
}

public CurrencyCode parmCurrency(CurrencyCode _currency = currency)
{
    currency = _currency;
    return currency;
}
